CREATE TABLE user (ID_USER BIGINT AUTO_INCREMENT NOT NULL, ADRESSE VARCHAR(255), EMAIL VARCHAR(255), MOTDEPASSE VARCHAR(255), NOM VARCHAR(255), PRIMARY KEY (ID_USER))
CREATE TABLE LignePanier (ID_LIGNE BIGINT AUTO_INCREMENT NOT NULL, QUANTITE INTEGER, panier_id BIGINT NOT NULL, produit_id BIGINT NOT NULL, PRIMARY KEY (ID_LIGNE))
CREATE TABLE panier (ID_PANIER BIGINT AUTO_INCREMENT NOT NULL, DATECREATION DATE, TOTAL DOUBLE, user_id BIGINT NOT NULL, PRIMARY KEY (ID_PANIER))
CREATE TABLE produit (ID_PRODUIT BIGINT AUTO_INCREMENT NOT NULL, DESCRIPTION_PRODUIT VARCHAR(255), IMAGE_PRODUIT VARCHAR(255), NOM_PRODUIT VARCHAR(255), PRIX_PRODUIT DOUBLE, STOCK BIGINT, PRIMARY KEY (ID_PRODUIT))
CREATE TABLE commande (ID_COMMANDE BIGINT AUTO_INCREMENT NOT NULL, DATECOMMANDE DATETIME, TOTAL DOUBLE, user_id BIGINT NOT NULL, PRIMARY KEY (ID_COMMANDE))
CREATE TABLE ligne_commande (ID BIGINT AUTO_INCREMENT NOT NULL, QUANTITE INTEGER, commande_id BIGINT NOT NULL, produit_id BIGINT NOT NULL, PRIMARY KEY (ID))
ALTER TABLE LignePanier ADD CONSTRAINT FK_LignePanier_panier_id FOREIGN KEY (panier_id) REFERENCES panier (ID_PANIER)
ALTER TABLE LignePanier ADD CONSTRAINT FK_LignePanier_produit_id FOREIGN KEY (produit_id) REFERENCES produit (ID_PRODUIT)
ALTER TABLE panier ADD CONSTRAINT FK_panier_user_id FOREIGN KEY (user_id) REFERENCES user (ID_USER)
ALTER TABLE commande ADD CONSTRAINT FK_commande_user_id FOREIGN KEY (user_id) REFERENCES user (ID_USER)
ALTER TABLE ligne_commande ADD CONSTRAINT FK_ligne_commande_commande_id FOREIGN KEY (commande_id) REFERENCES commande (ID_COMMANDE)
ALTER TABLE ligne_commande ADD CONSTRAINT FK_ligne_commande_produit_id FOREIGN KEY (produit_id) REFERENCES produit (ID_PRODUIT)
